import{_ as o,o as u,c as e,ai as a}from"./chunks/framework.scx6l_IK.js";const i=JSON.parse('{"title":"金刚经6分-法尚应舍","description":"","frontmatter":{},"headers":[],"relativePath":"60-原文段落/金刚经6分-法尚应舍.md","filePath":"60-原文段落/金刚经6分-法尚应舍.md","lastUpdated":1778155802000}'),q={name:"60-原文段落/金刚经6分-法尚应舍.md"};function r(_,t,s,p,n,c){return u(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="金刚经6分-法尚应舍" tabindex="-1">金刚经6分-法尚应舍 <a class="header-anchor" href="#金刚经6分-法尚应舍" aria-label="Permalink to &quot;金刚经6分-法尚应舍&quot;">​</a></h1><blockquote><p>来源：<a href="/01-Raw-Sources/6了空居士讲《金刚经》-第六分正信希有分20161007">6了空居士讲《金刚经》-第六分正信希有分20161007</a> 切分日期：2026-05-06</p></blockquote><hr><p><strong>是故不应取法，不应取非法。</strong></p><p>就是这个原因，所以你们不能执着法之相，也不能执著一切法都是空的，因此什么都不干，那落空也不对。</p><p><strong>以是义故，如来常说，汝等比丘，知我说法，如筏喻者，法尚应舍，何况非法！</strong></p><p>&quot;汝等比丘&quot;，因为那个时候在听佛祖讲法的很多都是&quot;千二百五十罗汉&quot;了，所以称他们为&quot;比丘&quot;。&quot;比丘&quot;是印度语，翻译成中国话就是&quot;乞士&quot;，&quot;乞&quot;是乞丐的&quot;乞&quot;。&quot;乞士&quot;是什么意思？&quot;上求佛法，下化众生&quot;，&quot;比丘&quot;就是这个意思。&quot;汝等比丘，知我说法，如筏喻者&quot;，就是说：我告诉你们种种修炼的方法，就像那个竹筏或者是木筏，你们遇到什么烦恼，我告诉你们什么方法，就是用这个方法将那个烦恼化掉了就好。就好像我们要过河就要利用这个竹排啊船啊渡我们载我们过去，过了河，就不能背着这个船继续赶路，这个船就留在河边给别人用了吧，就是这种意思。就是这个&quot;法&quot;是用来对治那个烦恼的，烦恼化解了，这个&quot;法&quot;也用不着了。</p><p>&quot;法尚应舍，何况非法&quot;，就是说这是正确的方法，只要事情解决了，这些都可以不要了。如果是错误的方法，那更是不要啦，是这个意思。所以说正确的&quot;法&quot;用完了，用不着了，也要&quot;舍&quot;，更何况那些不正确的，那就更加不要它了，是不是？</p>',8)])])}const l=o(q,[["render",r]]);export{i as __pageData,l as default};
